import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.json.*;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Allowlist of valid report types - but note: not used for column filtering
    private static final Set<String> VALID_REPORTS = Set.of(
        "sales_summary", "inventory", "customer_activity", "revenue");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String reportType = req.getParameter("type");
        String sortColumn = req.getParameter("sort");
        String dateFrom = req.getParameter("from");
        String dateTo = req.getParameter("to");
        String limit = req.getParameter("limit");

        if (reportType == null || !VALID_REPORTS.contains(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date format (basic check)
        if (dateFrom != null && !dateFrom.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date format");
            return;
        }
        if (dateTo != null && !dateTo.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Validate limit is numeric
        int rowLimit = 100;
        if (limit != null) {
            try {
                rowLimit = Math.min(Integer.parseInt(limit), 1000);
            } catch (NumberFormatException e) {
                rowLimit = 100;
            }
        }

        // Build query - sortColumn is user-controlled and injected directly
        // This is intentional for flexible reporting but creates SQL injection
        StringBuilder sql = new StringBuilder();
        sql.append("SELECT * FROM ").append(reportType);
        sql.append(" WHERE created_at >= ? AND created_at <= ?");

        if (sortColumn != null && !sortColumn.isEmpty()) {
            // Developer assumed frontend dropdown limits values
            // No server-side validation of sort column
            sql.append(" ORDER BY ").append(sortColumn);
        }
        sql.append(" LIMIT ").append(rowLimit);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(sql.toString())) {

            stmt.setString(1, dateFrom != null ? dateFrom : "2020-01-01");
            stmt.setString(2, dateTo != null ? dateTo : "2099-12-31");

            ResultSet rs = stmt.executeQuery();
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();

            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                for (int i = 1; i <= cols; i++) {
                    row.put(meta.getColumnLabel(i), rs.getObject(i));
                }
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            // Log but don't expose SQL errors to client
            getServletContext().log("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        // Export endpoint - reuses same logic
        doGet(req, resp);
    }
}
